#include <stdio.h>
static void cm_priolarm_dump(uint32_t n,uint16_t status,const apollo_overlay_state *s,const cm_native_io *io){unsigned i;unsigned char bytes[4130];uint16_t words[2065];words[0]=(uint16_t)n;words[1]=(uint16_t)(n>>16);words[2]=0;words[3]=status;for(i=0;i<2048u;++i)words[i+4u]=s->words[i];words[2052]=io->channel11;words[2053]=io->channel12;words[2054]=io->channel13;words[2055]=io->channel14;words[2056]=io->main_keys;words[2057]=io->navigation_keys;words[2058]=io->superbank;words[2059]=io->interrupt_enabled;words[2060]=io->trap31a;words[2061]=io->trap31b;words[2062]=io->trap32;words[2063]=io->executive_alarm;words[2064]=io->waitlist_alarm;for(i=0;i<2065u;++i){bytes[2u*i]=(unsigned char)words[i];bytes[2u*i+1u]=(unsigned char)(words[i]>>8);}if(fwrite(bytes,1,sizeof bytes,stdout)!=sizeof bytes)exit(2);}
